    // ---- Pass 2: Compute exp(x - max) and sum ----
    __aicore__ inline float ComputeSum(int32_t rowIdx, float maxVal)
    {
        sumLocal_ = sumBuf_.Get<float>();
        AscendC::Duplicate(sumLocal_, 0.0f, 1);
        reduceLocal_ = reduceBuf_.Get<float>();
        expLocal_ = expBuf_.Get<float>();
        shiftLocal_ = shiftBuf_.Get<float>();

        for (int by = 0; by < numTiles_; ++by) {
            const int colBase = by * tileN;
            const int validN = GetValidN(colBase);

            CopyInX(rowIdx, colBase, validN);
            xInLocal_ = xInQueue_.DeQue<dataType>();
            PrepareInputTensor(xLocal_, xInLocal_, validN);

            AscendC::Adds(shiftLocal_, xLocal_, -maxVal, validN);
            AscendC::Exp(expLocal_, shiftLocal_, validN);

            AscendC::ReduceSum<float>(reduceLocal_, expLocal_, reduceLocal_, validN);
            float tileSum = reduceLocal_.GetValue(0);
            float curSum = sumLocal_.GetValue(0) + tileSum;
            AscendC::Duplicate(sumLocal_, curSum, 1);

