            xInLocal_ = xInQueue_.DeQue<dataType>();
            PrepareInputTensor(xLocal_, xInLocal_, validN);

            AscendC::Adds(shiftLocal_, xLocal_, -maxVal, validN);
            AscendC::Exp(expLocal_, shiftLocal_, validN);
            AscendC::Muls(expLocal_, expLocal_, 1.0f / sumVal, validN);

            yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
            FinalizeOutputTensor(yOutLocal_, expLocal_, validN);
            yOutQueue_.EnQue(yOutLocal_);

            xInQueue_.FreeTensor(xInLocal_);
            CopyOutY(rowIdx, colBase, validN);
        }
