    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        float maxVal = ComputeMax(rowIdx);
        float sumVal = ComputeSum(rowIdx, maxVal);
        ComputeAndWrite(rowIdx, maxVal, sumVal);
    }

