// =========================================================================
// Dtype dispatch helper
// =========================================================================

template <template <typename> class Kernel, typename... ExtraArgs>
__aicore__ inline void DispatchSoftmax(
    GM_ADDR x, GM_ADDR y,
    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, int32_t tileN,
    int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        Kernel<float> kernel;
        kernel.Init(x, y, M, N, blockM, usedCoreNum, tasksPerCore, tileN);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        Kernel<half> kernel;
        kernel.Init(x, y, M, N, blockM, usedCoreNum, tasksPerCore, tileN);
        kernel.Process();
    } else {
        Kernel<bfloat16_t> kernel;
        kernel.Init(x, y, M, N, blockM, usedCoreNum, tasksPerCore, tileN);
        kernel.Process();
    }
}

// =========================================================================
// Kernel entry point
// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
// =========================================================================

