    GM_ADDR x, GM_ADDR y,
    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, int32_t tileN,
    int64_t dtypeFlag)
{
    DispatchSoftmax<InplaceAttnSoftmaxKernel>(
        x, y, M, N, blockM, usedCoreNum, tasksPerCore, tileN, dtypeFlag);
}
