// InplaceAttnSoftmax op_host — tiling calculation + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_inplace_attn_softmax.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_BLOCK_M = 64;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

at::Tensor inplace_attn_softmax(const at::Tensor &input)
{
    TORCH_CHECK(input.dim() >= 1, "input must have at least 1 dimension");
    TORCH_CHECK(
        input.scalar_type() == at::kFloat || input.scalar_type() == at::kHalf ||
            input.scalar_type() == at::kBFloat16,
        "input must be float16, float32, or bfloat16");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");

    // Flatten all but last dimension
    int64_t total_elements = input.numel();
    int32_t N = static_cast<int32_t>(input.sizes()[input.dim() - 1]);
    int32_t M = static_cast<int32_t>(total_elements / N);

    at::Tensor output = at::empty_like(input);

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (input.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (input.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());

    uint64_t ubSize = 0;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Block-level tiling
    int32_t mNum = (M + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
    int32_t usedCoreNum = std::min<int32_t>(static_cast<int32_t>(coreNum), std::max<int32_t>(1, mNum));
    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;

    // UB-level tiling: compute tileN based on UB size
    // Need buffers: xIn (tileN * dtype), yOut (tileN * dtype), reduce (tileN * float),
    //               exp (tileN * float), shift (tileN * float), cast (tileN * float),
    //               maxBuf (float), sumBuf (float)
    // Total UB for float32 path: ~5 * tileN * 4 + 8 bytes
    // For fp16/bf16 path: ~7 * tileN * 4 + 8 bytes (with cast buffers)
    // Conservative: use 1/10 of UB for our buffers
    uint32_t elemSize = (dtypeFlag == 0) ? 4 : 2;
    uint32_t tileN = static_cast<uint32_t>(ubSize / (10 * sizeof(float)));
    tileN = (tileN / 16) * 16;  // align to 16
    if (tileN < 16) {
        tileN = 16;
    }
    if (tileN > static_cast<uint32_t>(N)) {
        tileN = static_cast<uint32_t>(N);
    }
    // Ensure tileN is at least 16 and aligned
    if (tileN < 16) {
        tileN = 16;
    }

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    int32_t blockM = DEFAULT_BLOCK_M;
    int32_t tileN_i32 = static_cast<int32_t>(tileN);
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(inplace_attn_softmax, blockDim,
                    input, output,
                    M, N, blockM, usedCoreNum, tasksPerCore, tileN_i32,
                    dtypeFlag);

    return output;
}

}  // namespace ascend_kernel
