172	            float tileMax = reduceLocal_.GetValue(0);
173	            if (tileMax > maxLocal_.GetValue(0)) {
174	                AscendC::Duplicate(maxLocal_, tileMax, 1);
175	            }
176	            xInQueue_.FreeTensor(xInLocal_);
177	        }
178	        return maxLocal_.GetValue(0);
179	    }
