181	    // ---- Pass 2: Compute exp(x - max) and sum ----
182	    __aicore__ inline float ComputeSum(int32_t rowIdx, float maxVal)
183	    {
184	        sumLocal_ = sumBuf_.Get<float>();
185	        AscendC::Duplicate(sumLocal_, 0.0f, 1);
186	        reduceLocal_ = reduceBuf_.Get<float>();
187	        expLocal_ = expBuf_.Get<float>();
188	        shiftLocal_ = shiftBuf_.Get<float>();
189	
190	        for (int by = 0; by < numTiles_; ++by) {
191	            const int colBase = by * tileN;
192	            const int validN = GetValidN(colBase);
193	
194	            CopyInX(rowIdx, colBase, validN);
195	            xInLocal_ = xInQueue_.DeQue<dataType>();
196	            PrepareInputTensor(xLocal_, xInLocal_, validN);
197	
198	            AscendC::Adds(shiftLocal_, xLocal_, -maxVal, validN);
199	            AscendC::Exp(expLocal_, shiftLocal_, validN);
200	
201	            AscendC::ReduceSum<float>(reduceLocal_, expLocal_, reduceLocal_, validN);
202	            float tileSum = reduceLocal_.GetValue(0);
203	            float curSum = sumLocal_.GetValue(0) + tileSum;
204	            AscendC::Duplicate(sumLocal_, curSum, 1);
205	
206	            xInQueue_.FreeTensor(xInLocal_);
207	        }
208	        return sumLocal_.GetValue(0);
209	    }
