211	    // ---- Pass 3: Compute softmax = exp(x - max) / sum and write back ----
212	    __aicore__ inline void ComputeAndWrite(int32_t rowIdx, float maxVal, float sumVal)
213	    {
214	        expLocal_ = expBuf_.Get<float>();
215	        shiftLocal_ = shiftBuf_.Get<float>();
216	
217	        for (int by = 0; by < numTiles_; ++by) {
218	            const int colBase = by * tileN;
