224	
225	            AscendC::Adds(shiftLocal_, xLocal_, -maxVal, validN);
226	            AscendC::Exp(expLocal_, shiftLocal_, validN);
227	            AscendC::Muls(expLocal_, expLocal_, 1.0f / sumVal, validN);
228	
229	            yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
230	            FinalizeOutputTensor(yOutLocal_, expLocal_, validN);
231	            yOutQueue_.EnQue(yOutLocal_);
232	
233	            xInQueue_.FreeTensor(xInLocal_);
234	            CopyOutY(rowIdx, colBase, validN);
235	        }
