// AscendC InplaceAttnSoftmax kernel — Softmax along last dimension
// Supports float32, float16, bfloat16
// Row-wise computation: each row independently computes softmax

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// Softmax kernel — single row strategy with tile along N dimension
// =========================================================================

template <typename dataType>
class InplaceAttnSoftmaxKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y,
        int32_t M, int32_t N, int32_t usedCoreNum,
        int32_t tasksPerCore, int32_t tileN)
    {
        this->M = M;
        this->N = N;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->tileN = tileN;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(M) * N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);

        if ASCEND_IS_AIV {
            numTiles_ = (N + tileN - 1) / tileN;

            pipe.InitBuffer(xInQueue_, BUFFER_NUM, tileN * sizeof(dataType));
            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, tileN * sizeof(dataType));
            pipe.InitBuffer(maxBuf_, 16 * sizeof(float));
            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
            pipe.InitBuffer(reduceBuf_, tileN * sizeof(float));
            pipe.InitBuffer(expBuf_, tileN * sizeof(float));
            pipe.InitBuffer(shiftBuf_, tileN * sizeof(float));
            pipe.InitBuffer(castBuf_, tileN * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int rowIdx = coreIdx * tasksPerCore + localIdx;
                if (rowIdx < M) {
                    ProcessRow(rowIdx);
                }
            }
        }
    }

private:
    __aicore__ inline int32_t GetValidN(int32_t colBase) const
    {
        return (colBase + tileN <= N) ? tileN : (N - colBase);
    }

    __aicore__ inline void CopyInX(int32_t rowIdx, int32_t colBase, int32_t validN)
    {
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N + colBase], static_cast<uint32_t>(validN));
        xInQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void CopyOutY(int32_t rowIdx, int32_t colBase, int32_t validN)
    {
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N + colBase], yOutLocal_, static_cast<uint32_t>(validN));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline void PrepareInputTensor(
        AscendC::LocalTensor<float> &dst,
        AscendC::LocalTensor<dataType> &src,
        int32_t count)
    {
        dst = castBuf_.Get<float>();
        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::DataCopy(dst, src.template ReinterpretCast<float>(), count);
        } else {
            AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        }
        AscendC::PipeBarrier<PIPE_V>();
    }

    __aicore__ inline void FinalizeOutputTensor(
        AscendC::LocalTensor<dataType> &dst,
        AscendC::LocalTensor<float> &src,
        int32_t count)
    {
        if constexpr (!std::is_same_v<dataType, float>) {
            AscendC::Cast(dst, src, AscendC::RoundMode::CAST_ROUND, count);
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    // ---- Pass 1: Find max value for the row ----
    __aicore__ inline float ComputeMax(int32_t rowIdx)
    {
        maxLocal_ = maxBuf_.Get<float>();
        AscendC::Duplicate(maxLocal_, -3.402823466e+38f, 1);
        reduceLocal_ = reduceBuf_.Get<float>();

        for (int by = 0; by < numTiles_; ++by) {
            const int colBase = by * tileN;
            const int validN = GetValidN(colBase);

            CopyInX(rowIdx, colBase, validN);
            xInLocal_ = xInQueue_.DeQue<dataType>();
            PrepareInputTensor(xLocal_, xInLocal_, validN);

            // Use WholeReduceMax for row-wise max
            AscendC::WholeReduceMax<float>(reduceLocal_, xLocal_, validN, 1, 8);
            float tileMax = reduceLocal_.GetValue(0);
            if (tileMax > maxLocal_.GetValue(0)) {
                AscendC::Duplicate(maxLocal_, tileMax, 1);
            }
            xInQueue_.FreeTensor(xInLocal_);
        }
        return maxLocal_.GetValue(0);
    }

    // ---- Pass 2: Compute exp(x - max) and sum ----
    __aicore__ inline float ComputeSum(int32_t rowIdx, float maxVal)
    {
        sumLocal_ = sumBuf_.Get<float>();
        AscendC::Duplicate(sumLocal_, 0.0f, 1);
        reduceLocal_ = reduceBuf_.Get<float>();
        expLocal_ = expBuf_.Get<float>();
        shiftLocal_ = shiftBuf_.Get<float>();

        for (int by = 0; by < numTiles_; ++by) {
            const int colBase = by * tileN;
            const int validN = GetValidN(colBase);

            CopyInX(rowIdx, colBase, validN);
            xInLocal_ = xInQueue_.DeQue<dataType>();
            PrepareInputTensor(xLocal_, xInLocal_, validN);

            AscendC::Adds(shiftLocal_, xLocal_, -maxVal, validN);
            AscendC::Exp(expLocal_, shiftLocal_, validN);

            // Use WholeReduceSum for row-wise sum
            AscendC::WholeReduceSum<float>(reduceLocal_, expLocal_, validN, 1, 8);
            float tileSum = reduceLocal_.GetValue(0);
            float curSum = sumLocal_.GetValue(0) + tileSum;
            AscendC::Duplicate(sumLocal_, curSum, 1);

            xInQueue_.FreeTensor(xInLocal_);
        }
        return sumLocal_.GetValue(0);
    }

    // ---- Pass 3: Compute softmax = exp(x - max) / sum and write back ----
    __aicore__ inline void ComputeAndWrite(int32_t rowIdx, float maxVal, float sumVal)
    {
        expLocal_ = expBuf_.Get<float>();
        shiftLocal_ = shiftBuf_.Get<float>();

        for (int by = 0; by < numTiles_; ++by) {
            const int colBase = by * tileN;
            const int validN = GetValidN(colBase);

            CopyInX(rowIdx, colBase, validN);
            xInLocal_ = xInQueue_.DeQue<dataType>();
            PrepareInputTensor(xLocal_, xInLocal_, validN);

            AscendC::Adds(shiftLocal_, xLocal_, -maxVal, validN);
            AscendC::Exp(expLocal_, shiftLocal_, validN);
            AscendC::Muls(expLocal_, expLocal_, 1.0f / sumVal, validN);

            yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
            FinalizeOutputTensor(yOutLocal_, expLocal_, validN);
            yOutQueue_.EnQue(yOutLocal_);

            xInQueue_.FreeTensor(xInLocal_);
            CopyOutY(rowIdx, colBase, validN);
        }
    }

    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        float maxVal = ComputeMax(rowIdx);
        float sumVal = ComputeSum(rowIdx, maxVal);
        ComputeAndWrite(rowIdx, maxVal, sumVal);
    }

private:
    int32_t M = 0;
    int32_t N = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    int32_t tileN = 0;
    int numTiles_ = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> yGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maxBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> expBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> shiftBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
    AscendC::LocalTensor<float> xLocal_;
    AscendC::LocalTensor<float> maxLocal_;
    AscendC::LocalTensor<float> sumLocal_;
    AscendC::LocalTensor<float> reduceLocal_;
    AscendC::LocalTensor<float> expLocal_;
    AscendC::LocalTensor<float> shiftLocal_;
};

// =========================================================================
// Dtype dispatch helper
// =========================================================================

template <template <typename> class Kernel, typename... ExtraArgs>
__aicore__ inline void DispatchSoftmax(
    GM_ADDR x, GM_ADDR y,
    int32_t M, int32_t N, int32_t usedCoreNum,
    int32_t tasksPerCore, int32_t tileN,
    int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        Kernel<float> kernel;
        kernel.Init(x, y, M, N, usedCoreNum, tasksPerCore, tileN);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        Kernel<half> kernel;
        kernel.Init(x, y, M, N, usedCoreNum, tasksPerCore, tileN);
        kernel.Process();
    } else {
        Kernel<bfloat16_t> kernel;
        kernel.Init(x, y, M, N, usedCoreNum, tasksPerCore, tileN);
        kernel.Process();
    }
}

// =========================================================================
// Kernel entry point
// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
// =========================================================================

extern "C" __global__ __aicore__ void inplace_attn_softmax(
    GM_ADDR x, GM_ADDR y,
    int32_t M, int32_t N, int32_t usedCoreNum,
    int32_t tasksPerCore, int32_t tileN,
    int64_t dtypeFlag)
{
    DispatchSoftmax<InplaceAttnSoftmaxKernel>(
        x, y, M, N, usedCoreNum, tasksPerCore, tileN, dtypeFlag);
}
