44	// Softmax kernel
45	// =========================================================================
46	
47	template <typename dataType>
48	class InplaceAttnSoftmaxKernel {
49	public:
50	    __aicore__ inline void Init(
51	        GM_ADDR x, GM_ADDR y,
52	        int32_t M, int32_t N, int32_t usedCoreNum,
53	        int32_t tileN)
54	    {
55	        this->M = M;
56	        this->N = N;
57	        this->usedCoreNum = usedCoreNum;
58	        this->tileN = tileN;
59	
60	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), static_cast<uint64_t>(M) * N);
61	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);
62	
63	        if ASCEND_IS_AIV {
64	            numTiles_ = (N + tileN - 1) / tileN;
65	
66	            pipe.InitBuffer(xInQueue_, BUFFER_NUM, tileN * sizeof(dataType));
67	            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, tileN * sizeof(dataType));
68	            pipe.InitBuffer(maxBuf_, 16 * sizeof(float));
69	            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
70	            pipe.InitBuffer(reduceBuf_, tileN * sizeof(float));
71	            pipe.InitBuffer(expBuf_, tileN * sizeof(float));
72	            pipe.InitBuffer(shiftBuf_, tileN * sizeof(float));
73	            pipe.InitBuffer(castBuf_, tileN * sizeof(float));
74	        }
75	    }
76	
77	    __aicore__ inline void Process()
78	    {
79	        if ASCEND_IS_AIV {
80	            const int coreIdx = AscendC::GetBlockIdx();
81	            // Each core handles rows: coreIdx, coreIdx + usedCoreNum, coreIdx + 2*usedCoreNum, ...
82	            for (int rowIdx = coreIdx; rowIdx < M; rowIdx += usedCoreNum) {
83	                ProcessRow(rowIdx);
84	            }
85	        }
86	    }
87	
88	private:
89	    __aicore__ inline int32_t GetValidN(int32_t colBase) const
90	    {
91	        return (colBase + tileN <= N) ? tileN : (N - colBase);
92	    }
93	
94	    __aicore__ inline void CopyInX(int32_t rowIdx, int32_t colBase, int32_t validN)
95	    {
96	        xInLocal_ = xInQueue_.AllocTensor<dataType>();
97	        LoadGmToUb(xInLocal_, xGM_[static_cast<uint64_t>(rowIdx) * N + colBase], static_cast<uint32_t>(validN));
98	        xInQueue_.EnQue(xInLocal_);
99	    }
100	
101	    __aicore__ inline void CopyOutY(int32_t rowIdx, int32_t colBase, int32_t validN)
102	    {
103	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
104	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N + colBase], yOutLocal_, static_cast<uint32_t>(validN));
105	        yOutQueue_.FreeTensor(yOutLocal_);
106	    }
107	
108	    __aicore__ inline void PrepareInputTensor(
109	        AscendC::LocalTensor<float> &dst,
110	        AscendC::LocalTensor<dataType> &src,
111	        int32_t count)
112	    {
113	        dst = castBuf_.Get<float>();
114	        if constexpr (std::is_same_v<dataType, float>) {
115	            AscendC::DataCopy(dst, src.template ReinterpretCast<float>(), count);
116	        } else {
117	            AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
118	        }
119	        AscendC::PipeBarrier<PIPE_V>();
120	    }
121	
122	    __aicore__ inline void FinalizeOutputTensor(
123	        AscendC::LocalTensor<dataType> &dst,
124	        AscendC::LocalTensor<float> &src,
125	        int32_t count)
126	    {
127	        if constexpr (!std::is_same_v<dataType, float>) {
128	            AscendC::Cast(dst, src, AscendC::RoundMode::CAST_ROUND, count);
129	            AscendC::PipeBarrier<PIPE_V>();
130	        }
131	    }
132	
133	    // ---- Pass 1: Find max value for the row ----
134	    __aicore__ inline float ComputeMax(int32_t rowIdx)
135	    {
136	        maxLocal_ = maxBuf_.Get<float>();
137	        AscendC::Duplicate(maxLocal_, -3.402823466e+38f, 1);
138	        reduceLocal_ = reduceBuf_.Get<float>();
139	
140	        for (int by = 0; by < numTiles_; ++by) {
141	            const int colBase = by * tileN;
142	            const int validN = GetValidN(colBase);
143	
144	            CopyInX(rowIdx, colBase, validN);
145	            xInLocal_ = xInQueue_.DeQue<dataType>();
146	            PrepareInputTensor(xLocal_, xInLocal_, validN);
147	
148	            // Use scalar loop to find max (most reliable)
149	            float tileMax = -3.402823466e+38f;
150	            for (int i = 0; i < validN; ++i) {
151	                float val = xLocal_.GetValue(i);
152	                if (val > tileMax) {
153	                    tileMax = val;
154	                }
155	            }
156	            if (tileMax > maxLocal_.GetValue(0)) {
157	                AscendC::Duplicate(maxLocal_, tileMax, 1);
158	            }
159	            xInQueue_.FreeTensor(xInLocal_);
160	        }
161	        return maxLocal_.GetValue(0);
162	    }
163	
164	    // ---- Pass 2: Compute exp(x - max) and sum ----
165	    __aicore__ inline float ComputeSum(int32_t rowIdx, float maxVal)
166	    {
167	        sumLocal_ = sumBuf_.Get<float>();
168	        AscendC::Duplicate(sumLocal_, 0.0f, 1);
169	        expLocal_ = expBuf_.Get<float>();
170	        shiftLocal_ = shiftBuf_.Get<float>();
171	
172	        for (int by = 0; by < numTiles_; ++by) {
173	            const int colBase = by * tileN;
174	            const int validN = GetValidN(colBase);
175	
176	            CopyInX(rowIdx, colBase, validN);
177	            xInLocal_ = xInQueue_.DeQue<dataType>();
178	            PrepareInputTensor(xLocal_, xInLocal_, validN);
179	
180	            AscendC::Adds(shiftLocal_, xLocal_, -maxVal, validN);
181	            AscendC::Exp(expLocal_, shiftLocal_, validN);
182	
183	            // Use scalar loop to compute sum
184	            float tileSum = 0.0f;
185	            for (int i = 0; i < validN; ++i) {
186	                tileSum += expLocal_.GetValue(i);
187	            }
188	            float curSum = sumLocal_.GetValue(0) + tileSum;
189	            AscendC::Duplicate(sumLocal_, curSum, 1);
190	
191	            xInQueue_.FreeTensor(xInLocal_);
192	        }
193	        return sumLocal_.GetValue(0);
194	    }
195	
196	    // ---- Pass 3: Compute softmax = exp(x - max) / sum and write back ----
197	    __aicore__ inline void ComputeAndWrite(int32_t rowIdx, float maxVal, float sumVal)
198	    {
199	        expLocal_ = expBuf_.Get<float>();
200	        shiftLocal_ = shiftBuf_.Get<float>();
201	
202	        for (int by = 0; by < numTiles_; ++by) {
203	            const int colBase = by * tileN;
204	            const int validN = GetValidN(colBase);
205	
206	            CopyInX(rowIdx, colBase, validN);
207	            xInLocal_ = xInQueue_.DeQue<dataType>();
208	            PrepareInputTensor(xLocal_, xInLocal_, validN);
209	
210	            AscendC::Adds(shiftLocal_, xLocal_, -maxVal, validN);
211	            AscendC::Exp(expLocal_, shiftLocal_, validN);
212	            AscendC::Muls(expLocal_, expLocal_, 1.0f / sumVal, validN);
213	
214	            yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
215	            FinalizeOutputTensor(yOutLocal_, expLocal_, validN);
216	            yOutQueue_.EnQue(yOutLocal_);
217	
218	            xInQueue_.FreeTensor(xInLocal_);
219	            CopyOutY(rowIdx, colBase, validN);
220	        }
221	    }
222	
223	    __aicore__ inline void ProcessRow(int32_t rowIdx)
224	    {
225	        float maxVal = ComputeMax(rowIdx);
226	        float sumVal = ComputeSum(rowIdx, maxVal);
227	        ComputeAndWrite(rowIdx, maxVal, sumVal);
228	    }
