230	private:
231	    int32_t M = 0;
232	    int32_t N = 0;
233	    int32_t usedCoreNum = 0;
234	    int32_t tileN = 0;
235	    int numTiles_ = 0;
236	
237	    AscendC::TPipe pipe;
238	    AscendC::GlobalTensor<dataType> xGM_;
239	    AscendC::GlobalTensor<dataType> yGM_;
240	
241	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
242	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
243	    AscendC::TBuf<AscendC::TPosition::VECCALC> maxBuf_;
244	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
245	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
246	    AscendC::TBuf<AscendC::TPosition::VECCALC> expBuf_;
247	    AscendC::TBuf<AscendC::TPosition::VECCALC> shiftBuf_;
248	    AscendC::TBuf<AscendC::TPosition::VECCALC> castBuf_;
249	
250	    AscendC::LocalTensor<dataType> xInLocal_;
251	    AscendC::LocalTensor<dataType> yOutLocal_;
252	    AscendC::LocalTensor<float> xLocal_;
253	    AscendC::LocalTensor<float> maxLocal_;
254	    AscendC::LocalTensor<float> sumLocal_;
255	    AscendC::LocalTensor<float> reduceLocal_;
256	    AscendC::LocalTensor<float> expLocal_;
257	    AscendC::LocalTensor<float> shiftLocal_;
258	};
